<section class="workspace-page owner-support-page"><?php require __DIR__.'/owner_nav.php'; ?><div class="page-heading"><span class="eyebrow">خدمة المستخدمين</span><h1>بلاغات المساعدة والاشتراكات</h1><p>راجع مشاكل المستخدمين وطلبات الاشتراك والتقييمات، واكتب الرد وحدد الحالة حتى تعرف ما يحتاج متابعة.</p></div><?php if (!$requests): ?><div class="empty-state"><h2>لا توجد بلاغات بعد</h2><p>ستظهر هنا أي رسالة يرسلها مستخدم من مركز المساعدة أو طلب اشتراك.</p></div><?php else: ?><div class="support-admin-list"><?php foreach ($requests as $request): ?><article class="dashboard-card support-admin-card status-<?= e($request['status']) ?>"><div class="support-admin-head"><div><span class="owner-role-badge"><?= e($request['status']==='new'?'جديد':($request['status']==='in_progress'?'قيد المتابعة':'تمت المعالجة')) ?></span><h2><?= e($request['subject']) ?></h2><small><?= e($request['full_name']) ?> · <?= e($request['email']) ?> · <?= e(saudi_datetime($request['created_at'])) ?></small></div></div><div class="support-admin-message"><?= nl2br(e($request['message'])) ?></div><form method="post" action="/owner/support/update" class="support-admin-form"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><label class="field"><span>الحالة</span><select name="status"><option value="new" <?= $request['status']==='new'?'selected':'' ?>>جديد</option><option value="in_progress" <?= $request['status']==='in_progress'?'selected':'' ?>>قيد المتابعة</option><option value="resolved" <?= $request['status']==='resolved'?'selected':'' ?>>تمت المعالجة</option></select></label><label class="field"><span>رد أو ملاحظة للمستخدم</span><textarea name="owner_note" rows="3" placeholder="اكتب ما يحتاج المستخدم معرفته..."><?= e($request['owner_note']) ?></textarea></label><button class="button button-navy" type="submit">حفظ المتابعة</button></form></article><?php endforeach; ?></div><?php endif; ?>
<?php if (!empty($reviews)): ?><section class="dashboard-card reviews-admin-card"><div class="section-card-heading"><div><span class="card-label">آراء المستخدمين</span><h2>التقييمات الواردة</h2></div></div><div class="reviews-admin-list"><?php foreach ($reviews as $review): ?><article><div><strong><?= str_repeat('★',(int)$review['rating']) ?><?= str_repeat('☆',5-(int)$review['rating']) ?></strong><span><?= e($review['full_name']) ?> · <?= e(saudi_datetime($review['created_at'])) ?></span><p><?= nl2br(e($review['message']?:'بدون ملاحظة')) ?></p></div><form method="post" action="/owner/review/update"><?= csrf_field() ?><input type="hidden" name="review_id" value="<?= (int)$review['id'] ?>"><label class="toggle-field"><input type="checkbox" name="is_published" value="1" <?= (int)$review['is_published']?'checked':'' ?>><span>إظهار التقييم للعامة</span></label><input name="owner_note" value="<?= e($review['owner_note']) ?>" placeholder="ملاحظة داخلية"><button class="text-button" type="submit">حفظ</button></form></article><?php endforeach; ?></div></section><?php endif; ?></section>
